create table public.csa_sessions(token_hash text primary key,steam_id text not null,kind text not null check(kind in ('browser','device')),name text not null,created_at bigint not null,expires_at bigint not null);
create index on public.csa_sessions(steam_id,kind);
create table public.csa_flows(state_hash text primary key,challenge text not null,steam_id text,expires_at bigint not null);
create table public.csa_nonces(nonce text primary key,expires_at bigint not null);
create table public.csa_devices(id text primary key,token_hash text not null unique,expected_steam_id text not null,name text not null,expires_at bigint not null);
create index on public.csa_devices(expected_steam_id);
create table public.csa_progress(key text primary key,steam_id text not null,game text not null,achievement text not null,current integer not null check(current>=0),unlocked_at bigint,updated_at bigint not null);
create index on public.csa_progress(steam_id);
create table public.csa_packs(id text primary key,owner text not null,title text not null,author text not null,description text not null,game text not null,version text not null,payload jsonb not null,count integer not null,downloads integer not null default 0,created_at bigint not null);
create index on public.csa_packs(owner);
create table public.csa_rates(key text primary key,count integer not null,expires_at bigint not null);
create table public.csa_profiles(steam_id text primary key,name text not null,avatar text not null,updated_at bigint not null);
-- Only the authenticated server may access these tables; browsers never receive its key.
do $$ declare t text; begin foreach t in array array['sessions','flows','nonces','devices','progress','packs','rates','profiles'] loop execute format('alter table public.csa_%I enable row level security',t); execute format('revoke all on public.csa_%I from anon,authenticated',t); execute format('grant all on public.csa_%I to service_role',t); end loop; end $$;
create function public.csa_exchange(s text,c text,secret_hash text,ts bigint) returns text language plpgsql security invoker set search_path='' as $$ declare account text; begin delete from public.csa_flows where state_hash=s and challenge=c and expires_at>ts and steam_id is not null returning steam_id into account; if account is null then raise exception 'Invalid or expired sign-in'; end if; insert into public.csa_sessions values(secret_hash,account,'browser','Website',ts,ts+2592000); return account; end $$;
create function public.csa_approve(d text,account text,ts bigint) returns boolean language plpgsql security invoker set search_path='' as $$ declare item public.csa_devices; begin delete from public.csa_devices where id=d and expected_steam_id=account and expires_at>ts returning * into item; if item.id is null then return false; end if; insert into public.csa_sessions values(item.token_hash,account,'device',item.name,ts,ts+15552000); return true; end $$;
create function public.csa_sync(account text,items jsonb,ts bigint) returns void language plpgsql security invoker set search_path='' as $$ begin insert into public.csa_progress as old(key,steam_id,game,achievement,current,unlocked_at,updated_at) select account||':'||x.game||':'||x.achievement,account,x.game,x.achievement,x.current,x.unlocked_at,ts from jsonb_to_recordset(items) as x(game text,achievement text,current integer,unlocked_at bigint) on conflict(key) do update set current=greatest(old.current,excluded.current),unlocked_at=least(old.unlocked_at,excluded.unlocked_at),updated_at=excluded.updated_at; end $$;
create function public.csa_rate(k text,ts bigint) returns integer language plpgsql security invoker set search_path='' as $$ declare n integer; begin delete from public.csa_rates where expires_at<ts; insert into public.csa_rates values(k,1,ts+120) on conflict(key) do update set count=public.csa_rates.count+1 returning count into n; return n; end $$;
create function public.csa_upload(account text,pack jsonb,ts bigint,pack_id text) returns boolean language plpgsql security invoker set search_path='' as $$ begin perform pg_advisory_xact_lock(hashtextextended(account,0)); if (select count(*) from public.csa_packs where owner=account)>=20 then return false; end if; insert into public.csa_packs(id,owner,title,author,description,game,version,payload,count,created_at) values(pack_id,account,pack->>'title',pack->>'author',pack->>'description',pack->>'game',pack->>'version',pack,jsonb_array_length(pack->'achievements'),ts*1000); return true; end $$;
revoke all on function public.csa_exchange(text,text,text,bigint),public.csa_approve(text,text,bigint),public.csa_sync(text,jsonb,bigint),public.csa_rate(text,bigint),public.csa_upload(text,jsonb,bigint,text) from public,anon,authenticated;
grant execute on function public.csa_exchange(text,text,text,bigint),public.csa_approve(text,text,bigint),public.csa_sync(text,jsonb,bigint),public.csa_rate(text,bigint),public.csa_upload(text,jsonb,bigint,text) to service_role;
